import SwiftUI

/// The licenses of the code compiled into Xipper (generated by scripts/make-acknowledgements.sh),
/// as the BSD and MIT licenses ask for binary distributions.
struct AcknowledgementsView: View {
    private let text: String = Bundle.main.url(forResource: "Acknowledgements", withExtension: "txt")
        .flatMap { try? String(contentsOf: $0, encoding: .utf8) } ?? String(localized: "Testo delle licenze non trovato.")

    var body: some View {
        ScrollView {
            Text(text)
                .font(.system(.callout, design: .monospaced))
                .textSelection(.enabled)
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(20)
        }
        .frame(minWidth: 560, minHeight: 420)
    }
}
